# p068 spring scale (hanging dial balance) kinematics. mm, front view: x right, y up, z toward the viewer. Pinion/needle axis at (0,0) along z.
# Load L(t) kg is scripted (weights placed / lifted); the crossbar drop d(t) is SOLVED from a damped spring (k = 2 kg per 2*pi mm, zeta 0.45),
# Hooke's law: rest drop D = L / K. The rack is fixed to the crossbar; it rolls on the pinion's pitch circle: needle angle = d / R_PITCH (clockwise).
# The pinion profile is GENERATED by the rack (shapely envelope), so the rack (thinner by the backlash) never overlaps it.
import json, math, numpy as np
from shapely.geometry import Polygon, Point
from shapely.ops import unary_union
from shapely import affinity
FPS_K = 120; LOOP = 25.0; MOD = 1.0; Z = 12; RP = MOD * Z / 2; PITCH = math.pi * MOD; PA = math.radians(20)
DIAL_SPAN = 300.0; DIAL_MAX = 10.0                     # 0-10 kg over 300 deg
K = (2.0 / 60.0) * (180 / math.pi) / RP                # kg per mm so that 2 kg -> 60 deg
D2 = 2.0 / K                                           # 6.283 mm for 2 kg
RACK_X = RP                                            # rack pitch line x (right of the pinion)
def rack_poly(y0, thick, y_lo=-40, y_hi=60, back=12.0, ha=1.0):  # rack teeth point toward -x; tooth centred at y0 + n*PITCH
    pts = [(back, y_lo)]; ha, hd = ha * MOD, 1.25 * MOD; n0 = int(math.floor((y_lo - y0) / PITCH)) - 1; n1 = int(math.ceil((y_hi - y0) / PITCH)) + 1
    for n in range(n0, n1 + 1):
        yc = y0 + n * PITCH; s = thick / 2; tA = math.tan(PA)
        tip_h = s - ha * tA; root_h = s + hd * tA
        pts += [(RACK_X + hd, yc - root_h), (RACK_X - ha, yc - tip_h), (RACK_X - ha, yc + tip_h), (RACK_X + hd, yc + root_h)]
    pts += [(back, y_hi)]; P = Polygon(pts).buffer(0); return P.intersection(Polygon([(-50, y_lo), (back, y_lo), (back, y_hi), (-50, y_hi)]))
# generate the pinion: blank (addendum circle) minus the cutter rack (full thickness PITCH/2) over the rolling motion
blank = Point(0, 0).buffer(RP + MOD, 256); cuts = []
for s in np.linspace(-math.pi * RP - 2 * PITCH, math.pi * RP + 2 * PITCH, 721):
    cut = rack_poly(PITCH / 2 - s, PITCH / 2, y_lo=-12, y_hi=12, ha=1.25)   # cutter: full-thickness teeth, deeper tip (root clearance)
    # rolling: rack moves down by s => pinion turns clockwise by s/RP; in the pinion frame the rack turns counter-clockwise
    cuts.append(affinity.rotate(cut, s / RP, origin=(0, 0), use_radians=True))
pin = blank.difference(unary_union(cuts)).buffer(0)
pin = max(pin.geoms, key=lambda g: g.area) if pin.geom_type == 'MultiPolygon' else pin
pin = pin.simplify(0.01)
BACKLASH = 0.12
def rack_scene(d): return rack_poly(PITCH / 2 - d, PITCH / 2 - BACKLASH, y_lo=-6 - d, y_hi=30 - d)
# ---------- load script ----------
sm = lambda u: (lambda v: v * v * (3 - 2 * v))(min(1, max(0, u)))
EV = {'drop1': 0.15, 'cut': 1.0, 'place1': 7.3, 'place2': 11.6, 'lift': 23.2, 'reset': 24.4}
def LOAD(t):
    if t < EV['drop1']: return 0.0
    if t < EV['cut']: return 2.0
    if t < EV['place1']: return 0.0
    if t < EV['place2']: return 2.0 * sm((t - EV['place1']) / 0.25)
    if t < EV['lift']: return 2.0 + 2.0 * sm((t - EV['place2']) / 0.12)
    return 4.0 * (1 - sm((t - EV['lift']) / 0.6))
def SLOW(t): return 2.6 if 11.5 < t < 14.6 else 1.0
W0 = 2 * math.pi * 1.5; ZETA = 0.45
dt = 1 / FPS_K; N = int(round(LOOP * FPS_K)) + 1; rows = []; d = 0.0; v = 0.0
for i in range(N):
    t = i * dt
    if abs(t - EV['cut']) < dt / 2: d = 0.0; v = 0.0            # hard cut back to the empty scale
    D = LOAD(t) / K; w = W0 / SLOW(t)
    for _ in range(8):
        a = w * w * (D - d) - 2 * ZETA * w * v; v += a * dt / 8; d += v * dt / 8
    if d < 0: d = 0.0; v = 0.0                                   # zero stop: the crossbar rests on the casing stop at no load
    if t > EV['reset']: d *= 0.0; v = 0.0
    rows.append([round(t, 4), round(d, 5), round(-d / RP * 180 / math.pi, 4), round(LOAD(t), 3)])
json.dump(rows, open('kin.json', 'w'), separators=(',', ':'))
pc = list(pin.exterior.coords)[:-1]
json.dump({'LOOP': LOOP, 'FPS_K': FPS_K, 'RP': RP, 'MOD': MOD, 'PITCH': PITCH, 'K': K, 'D2': D2, 'RACK_X': RACK_X, 'BACKLASH': BACKLASH,
           'DIAL_SPAN': DIAL_SPAN, 'DIAL_MAX': DIAL_MAX, 'EV': EV, 'PINION': [[round(x, 3), round(y, 3)] for x, y in pc],
           'RACK0': [[round(x, 3), round(y, 3)] for x, y in list(rack_scene(0).exterior.coords)[:-1]]}, open('geom.json', 'w'), indent=0)
print('K %.4f kg/mm, 2 kg -> %.3f mm, pinion pts %d, area %.1f' % (K, D2, len(pc), pin.area))
for tt in [0, 0.15, 0.4, 0.9, 1.0, 7.3, 8.0, 9.5, 11.6, 13, 14.5, 20, 23.2, 24.0, 24.4, 25.0]:
    r = rows[int(round(tt * FPS_K))]; print(tt, r)
print('d range', min(r[1] for r in rows), max(r[1] for r in rows))
